package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;

final class ServiceOutagesBrowserAcceptance {
 static void click(Page p,String name){p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName(name).setExact(true)).press("Enter");}
 static void run(BrowserTest h)throws Exception {
  String ci;try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","OutageBrowserOperator","role","agent","password",WorkflowSupport.PASSWORD));ci=Service.create(db,"cmdb_ci",map("short_description","Customer access service <script>"),"admin").get("sys_id").toString();db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"OutageBrowserOperator");page.navigate(h.base()+"/record/cmdb_ci/"+ci);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Outages and recorded availability")).press("Enter");assertThat(page.locator("main")).containsText("No outage entries recorded");page.getByLabel("Observation type").selectOption("outage");page.getByLabel("Outage summary").fill("Access unavailable <script>");page.getByLabel("Begin (UTC)",new Page.GetByLabelOptions().setExact(true)).fill(ServiceOutagesAcceptance.at(0));page.getByLabel("Observed evidence").fill("Confirmed user access failure <script>");click(page,"Record outage evidence");assertThat(page.locator("main")).containsText("Current recorded status: outage");assertThat(page.locator("main")).containsText("outage · ongoing · Revision 1");page.getByLabel("Recovery end (UTC)").fill(ServiceOutagesAcceptance.at(50));page.getByLabel("Recovery evidence").fill("Verified successful access after recovery");click(page,"Record recovery for Access unavailable <script>");assertThat(page.locator("main")).containsText("outage · ended · Revision 2");page.getByLabel("Reporting window start (UTC)").fill(ServiceOutagesAcceptance.at(0));page.getByLabel("Reporting window end (UTC)").fill(ServiceOutagesAcceptance.at(100));click(page,"Calculate recorded availability");assertThat(page.locator("main")).containsText("50.0000% recorded availability");page.locator("details summary").press("Enter");assertThat(page.locator("details")).containsText("Verified successful access after recovery");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/outage-recovery-light.png")).setFullPage(true));click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertThat(page.locator("main script")).hasCount(0);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/outage-report-dark.png")).setFullPage(true));page.getByLabel("Cancellation reason").fill("Corrected the logged service identity; retain original evidence");click(page,"Cancel entry Access unavailable <script>");assertThat(page.locator("main")).containsText("outage · cancelled · Revision 3");page.getByLabel("Reporting window start (UTC)").fill(ServiceOutagesAcceptance.at(0));page.getByLabel("Reporting window end (UTC)").fill(ServiceOutagesAcceptance.at(100));click(page,"Calculate recorded availability");assertThat(page.locator("main")).containsText("100.0000% recorded availability");assertThat(page.locator("main")).containsText("does not prove monitored uptime");try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(int n=0;n<100;n++){var earlier=ServiceOutagesAcceptance.body("planned",ServiceOutagesAcceptance.at(-1000),ServiceOutagesAcceptance.at(-900));earlier.put("summary","Earlier verified maintenance");ServiceOutages.save(db,ci,earlier,System.currentTimeMillis());}db.connection.commit();}page.reload();page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Older entries")).press("Enter");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Earlier verified maintenance").setExact(true))).hasCount(1);assertThat(page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Older entries"))).hasCount(0);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Newer entries")).press("Enter");assertThat(page.locator("main")).containsText("Access unavailable <script>");
  }
 }
}
